import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    a=list(map(int,data.split()));n,S=a[:2];v=a[2:];d=[S+1]*(S+1);d[0]=0
    for i in range(1,S+1):
        for x in v:
            if x<=i:d[i]=min(d[i],d[i-x]+1)
    return -1 if d[S]>S else d[S]

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
